// Generates src/generated/<api>.ts from spec/<api>-v<n>.yaml with openapi-typescript.
//
//   npm run generate
//
// The specs in spec/ are copies of sendx-api's openapi/*.yaml, taken by the
// sync-spec workflow; never edit them or the generated files by hand.
//
// One change to openapi-typescript's output: a string enum with two or more
// values becomes "open" (`"a" | "b" | (string & {})`), because Reeds adds
// values inside a version (a new delivery status, a new service). Editors still
// suggest the known values, and an unknown one doesn't fail to compile.
// Single-value enums stay exact: they are discriminants (an event's `type`,
// an envelope's `status`), and opening them would stop TypeScript narrowing.
import { readFileSync, writeFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import openapiTS, { astToString } from "openapi-typescript";
import ts from "typescript";

const root = fileURLToPath(new URL("..", import.meta.url));

/** Each API module: its spec and the generated file. */
const APIS = [{ name: "shipping", spec: "spec/shipping-v1.yaml", out: "src/generated/shipping.ts" }];

const anyString = ts.factory.createParenthesizedType(
  ts.factory.createIntersectionTypeNode([ts.factory.createKeywordTypeNode(ts.SyntaxKind.StringKeyword), ts.factory.createTypeLiteralNode([])]),
);

const openEnum = (schema) => {
  const values = schema.enum;
  if (!Array.isArray(values) || values.length < 2 || !values.every((value) => typeof value === "string")) return undefined;
  const literals = values.map((value) => ts.factory.createLiteralTypeNode(ts.factory.createStringLiteral(value)));
  const union = ts.factory.createUnionTypeNode([...literals, anyString]);
  return schema.nullable ? ts.factory.createUnionTypeNode([union, ts.factory.createLiteralTypeNode(ts.factory.createNull())]) : union;
};

for (const api of APIS) {
  const source = readFileSync(`${root}/${api.spec}`, "utf8");
  const ast = await openapiTS(source, { transform: openEnum, alphabetize: false, exportType: false, defaultNonNullable: false });
  const header = `// Generated by scripts/generate.mjs from ${api.spec}. Do not edit: run \`npm run generate\`.\n/* eslint-disable */\n`;
  writeFileSync(`${root}/${api.out}`, header + astToString(ast));
  console.log(`${api.spec} -> ${api.out}`);
}
